off = set(holidays)

def _count_forward(lo: date, hi: date) -> int:
    count = 0
    day = lo + ONE_DAY
    while day <= hi:
        if day.weekday() < 5:
            count += 1
        day += ONE_DAY
    holiday_count = sum(1 for h in off if lo < h <= hi)
    return count - holiday_count

if end < start:
    return -_count_forward(end, start)
